<?php
/** TEMP PS S1685 nm — DEPLOY naujas mu-plugin petshop-planas-langas.php v1.0.0 (Q4 plano langas) + petshop-pakartoti.php v1.1.5 (_ps_pakartoti_is žymė); token_get_all, heartbeat, rollback. */
add_action('init', function(){
  if (!isset($_GET['ps_s1685nm'])) return; $o=array('v'=>'S1685 nm'); $f=WPMU_PLUGIN_DIR.'/petshop-planas-langas.php'; $g=WPMU_PLUGIN_DIR.'/petshop-pakartoti.php'; $bd=WP_CONTENT_DIR.'/uploads/ps-backups';
  if(file_exists($f)||class_exists('Petshop_Planas_Langas')){ $o['STOP']='vardas/klasė užimti'; echo json_encode($o); exit; }
  $np=base64_decode(''); $nq=base64_decode(''); if(md5($np)!=='4748765b7352a164b12ce8a003de5cf9'||md5($nq)!=='33d4756e88079996092f8ab767776ea6'){ $o['STOP']='md5'; echo json_encode($o); exit; }
  try { token_get_all($np, TOKEN_PARSE); token_get_all($nq, TOKEN_PARSE); } catch (Throwable $e) { $o['STOP']=$e->getMessage(); echo json_encode($o); exit; }
  copy($g,$bd.'/petshop-pakartoti.php.bak_s1685g'); file_put_contents($f,$np); file_put_contents($g,$nq); if(function_exists('opcache_invalidate')){ opcache_invalidate($f,true); opcache_invalidate($g,true); } $o['md5']=array(md5_file($f),md5_file($g));
  $hb=wp_remote_get(home_url('/'),array('timeout'=>20,'sslverify'=>false)); $code=is_wp_error($hb)?0:wp_remote_retrieve_response_code($hb); $o['heartbeat']=$code; if($code>=500||$code===0){ unlink($f); copy($bd.'/petshop-pakartoti.php.bak_s1685g',$g); $o['ROLLBACK']=1; }
  header('Content-Type: application/json; charset=utf-8'); echo json_encode($o); exit;
});
